//! Instance `KeyHash` for `no_std` targets (hdds-micro).
//!
//! hdds-micro has no `KeyHash` writer and no MD5, so a generated file with a
//! keyed type carries its own: a `KeyHolder` writer that keeps the first 16
//! bytes of the `PLAIN_CDR2` big-endian serialization and streams every byte
//! through an RFC 1321 MD5, with no allocation. `compute_key()` writes the
//! `KeyHolder` members in member-id order (the `KeyHolder` model shared with the
//! Rust backend) and picks the padded or the MD5 form from the maximum size
//! computed at generation time (RTPS 2.5 9.6.4.8 step 5).

#![allow(clippy::uninlined_format_args)]

use std::fmt::Write as _;

use super::super::key_holder::{KhUnion, TypeIndex, MD5_K, MD5_S};
use super::super::rust_backend::key_hash::{
    key_holder_writes, union_disc_literal, union_key_holder_method,
};
use super::MicroGenerator;
use crate::ast::{Struct, Union};

/// Name of the generated module holding the writer.
const MODULE: &str = "__hdds_key_hash";

fn table(values: &[u32; 64], hex: bool) -> String {
    let mut out = String::new();
    for (i, v) in values.iter().enumerate() {
        if i % 8 == 0 {
            out.push_str("\n        ");
        }
        if hex {
            let _ = write!(out, "0x{v:08x}, ");
        } else {
            let _ = write!(out, "{v}, ");
        }
    }
    out
}

/// The writer module, emitted once at the top of a file with a keyed type.
// codegen function - line count from template output
#[allow(clippy::too_many_lines)]
pub(super) fn writer_module() -> String {
    format!(
        r"/// KeyHash writer for `compute_key()` (generated by hddsgen): the
/// `KeyHolder` serialized as `PLAIN_CDR2` big endian, alignment capped at 4,
/// reduced to 16 bytes by zero padding or MD5 (RTPS 2.5 9.6.4.8). No
/// allocation.
#[doc(hidden)]
#[allow(dead_code, clippy::all, clippy::pedantic)]
pub mod {m} {{
    const K: [u32; 64] = [{k}
    ];
    const S: [u32; 64] = [{s}
    ];

    /// MD5 (RFC 1321), streaming.
    struct Md5 {{
        state: [u32; 4],
        block: [u8; 64],
        used: usize,
        total: u64,
    }}

    impl Md5 {{
        const fn new() -> Self {{
            Self {{
                state: [0x6745_2301, 0xefcd_ab89, 0x98ba_dcfe, 0x1032_5476],
                block: [0; 64],
                used: 0,
                total: 0,
            }}
        }}

        fn compress(state: &mut [u32; 4], block: &[u8; 64]) {{
            let mut m = [0u32; 16];
            let mut i = 0;
            while i < 16 {{
                m[i] = u32::from_le_bytes([
                    block[4 * i],
                    block[4 * i + 1],
                    block[4 * i + 2],
                    block[4 * i + 3],
                ]);
                i += 1;
            }}
            let (mut a, mut b, mut c, mut d) = (state[0], state[1], state[2], state[3]);
            let mut j = 0;
            while j < 64 {{
                let (f, g) = match j / 16 {{
                    0 => ((b & c) | (!b & d), j),
                    1 => ((d & b) | (!d & c), (5 * j + 1) % 16),
                    2 => (b ^ c ^ d, (3 * j + 5) % 16),
                    _ => (c ^ (b | !d), (7 * j) % 16),
                }};
                let f = f.wrapping_add(a).wrapping_add(K[j]).wrapping_add(m[g]);
                a = d;
                d = c;
                c = b;
                b = b.wrapping_add(f.rotate_left(S[j]));
                j += 1;
            }}
            state[0] = state[0].wrapping_add(a);
            state[1] = state[1].wrapping_add(b);
            state[2] = state[2].wrapping_add(c);
            state[3] = state[3].wrapping_add(d);
        }}

        fn update(&mut self, data: &[u8]) {{
            for &byte in data {{
                self.block[self.used] = byte;
                self.used += 1;
                self.total = self.total.wrapping_add(1);
                if self.used == 64 {{
                    let block = self.block;
                    Self::compress(&mut self.state, &block);
                    self.used = 0;
                }}
            }}
        }}

        fn finish(mut self) -> [u8; 16] {{
            let bits = self.total.wrapping_mul(8);
            self.update(&[0x80]);
            while self.used != 56 {{
                self.update(&[0]);
            }}
            self.update(&bits.to_le_bytes());
            let mut out = [0u8; 16];
            let mut i = 0;
            while i < 4 {{
                out[4 * i..4 * i + 4].copy_from_slice(&self.state[i].to_le_bytes());
                i += 1;
            }}
            out
        }}
    }}

    /// Text a `wstring` key holds, as UTF-16 code units.
    pub trait WideText {{
        fn unit_count(&self) -> usize;
        fn for_each_unit(&self, f: &mut dyn FnMut(u16));
    }}

    impl WideText for str {{
        fn unit_count(&self) -> usize {{
            self.encode_utf16().count()
        }}
        fn for_each_unit(&self, f: &mut dyn FnMut(u16)) {{
            for unit in self.encode_utf16() {{
                f(unit);
            }}
        }}
    }}

    /// Code points, as the micro mapping of `wstring<N>` holds them.
    impl WideText for [u32] {{
        fn unit_count(&self) -> usize {{
            self.iter()
                .map(|&c| char::from_u32(c).map_or(1, char::len_utf16))
                .sum()
        }}
        fn for_each_unit(&self, f: &mut dyn FnMut(u16)) {{
            for &c in self {{
                let mut buf = [0u16; 2];
                match char::from_u32(c) {{
                    Some(ch) => {{
                        for unit in ch.encode_utf16(&mut buf) {{
                            f(*unit);
                        }}
                    }}
                    None => f(u16::try_from(c).unwrap_or(0xfffd)),
                }}
            }}
        }}
    }}

    /// The `KeyHolder` writer: same calls as `hdds::core::key_hash`.
    pub struct KeyHolderWriter {{
        head: [u8; 16],
        len: usize,
        md5: Md5,
    }}

    impl KeyHolderWriter {{
        pub const fn new() -> Self {{
            Self {{
                head: [0; 16],
                len: 0,
                md5: Md5::new(),
            }}
        }}

        fn extend(&mut self, bytes: &[u8]) {{
            for &byte in bytes {{
                if self.len < 16 {{
                    self.head[self.len] = byte;
                }}
                self.len += 1;
            }}
            self.md5.update(bytes);
        }}

        fn put(&mut self, bytes: &[u8]) {{
            let align = if bytes.len() < 4 {{ bytes.len() }} else {{ 4 }};
            while align > 1 && self.len % align != 0 {{
                self.extend(&[0]);
            }}
            self.extend(bytes);
        }}

        pub fn write_bool(&mut self, v: bool) {{
            self.extend(&[u8::from(v)]);
        }}
        pub fn write_u8(&mut self, v: u8) {{
            self.extend(&[v]);
        }}
        pub fn write_i8(&mut self, v: i8) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_u16(&mut self, v: u16) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_i16(&mut self, v: i16) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_u32(&mut self, v: u32) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_i32(&mut self, v: i32) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_u64(&mut self, v: u64) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_i64(&mut self, v: i64) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_f32(&mut self, v: f32) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_f64(&mut self, v: f64) {{
            self.put(&v.to_be_bytes());
        }}
        pub fn write_octets(&mut self, v: &[u8]) {{
            self.extend(v);
        }}
        pub fn write_string(&mut self, v: &str) {{
            self.write_u32(u32::try_from(v.len().saturating_add(1)).unwrap_or(u32::MAX));
            self.extend(v.as_bytes());
            self.extend(&[0]);
        }}
        /// `wstring`: a 4-byte length counting BYTES of UTF-16, then the
        /// code units. Takes the text as `str` (unbounded `wstring`) or as
        /// code points (`wstring<N>`, a `heapless::Vec<u32, N>`).
        pub fn write_wstring<T: WideText + ?Sized>(&mut self, v: &T) {{
            self.write_u32(u32::try_from(v.unit_count().saturating_mul(2)).unwrap_or(u32::MAX));
            v.for_each_unit(&mut |unit: u16| self.extend(&unit.to_be_bytes()));
        }}

        /// The `KeyHash`. `padded`: the `KeyHolder`'s maximum serialized size
        /// is at most 16 bytes. A serialization longer than 16 bytes is
        /// hashed whatever `padded` says, never truncated.
        pub fn finish(self, padded: bool) -> [u8; 16] {{
            if padded && self.len <= 16 {{
                self.head
            }} else {{
                self.md5.finish()
            }}
        }}
    }}
}}

",
        m = MODULE,
        k = table(&MD5_K, true),
        s = table(&MD5_S, false)
    )
}

/// Whether some structure of the file has a `KeyHolder` the model covers.
pub(super) fn file_needs_writer(ast: &crate::ast::IdlFile, idx: &TypeIndex) -> bool {
    fn walk(defs: &[crate::ast::Definition], idx: &TypeIndex) -> bool {
        defs.iter().any(|d| match d {
            crate::ast::Definition::Struct(s) => {
                matches!(idx.key_holder(s), Ok(Some(kh)) if kh.base_member().is_none())
            }
            // A union's hidden method names the writer whether or not a
            // keyed type reaches it.
            crate::ast::Definition::Union(u) => covered_union(u, idx).is_some(),
            crate::ast::Definition::Module(m) => walk(&m.definitions, idx),
            _ => false,
        })
    }
    walk(&ast.definitions, idx)
}

/// The `compute_key()` method of `s`.
pub(super) fn compute_key_method(s: &Struct, idx: &TypeIndex) -> String {
    let mut out = String::new();
    out.push_str(
        "\n    /// Instance KeyHash (RTPS 2.5 9.6.4.8): the KeyHolder serialized as\n    \
         /// `PLAIN_CDR2` big endian, zero-padded to 16 bytes when its maximum size\n    \
         /// is at most 16, its MD5 otherwise. All zeros for a type without key.\n",
    );
    out.push_str("    #[must_use]\n");
    out.push_str("    #[allow(clippy::all, clippy::pedantic)]\n");
    out.push_str("    pub fn compute_key(&self) -> [u8; 16] {\n");
    // The micro KeyHash does not read base members (its structs hold them
    // in a `base` field since the data path serializes them).
    let holder = idx.key_holder(s).and_then(|kh| {
        kh.map_or(Ok(None), |kh| {
            kh.base_member().map_or(Ok(Some(kh)), |(member, base)| {
                Err(format!(
                    "member `{member}` of base `{base}` is not read by this backend's KeyHash"
                ))
            })
        })
    });
    match holder {
        Ok(Some(kh)) => {
            let _ = writeln!(
                out,
                "        let mut writer = {MODULE}::KeyHolderWriter::new();"
            );
            out.push_str("        {\n            let w = &mut writer;\n");
            out.push_str(&key_holder_writes(&kh, "self", 3, false));
            out.push_str("        }\n");
            let _ = writeln!(out, "        writer.finish({})", kh.is_padded_form());
        }
        Ok(None) => out.push_str("        [0u8; 16]\n"),
        Err(reason) => {
            let reason = reason.replace(['\n', '\r'], " ");
            let _ = writeln!(
                out,
                "        // No KeyHolder generated: the key of this type is not covered by\n        \
                 // hddsgen's KeyHash model ({reason}). All samples share the zero hash."
            );
            out.push_str("        [0u8; 16]\n");
        }
    }
    out.push_str("    }\n");
    out
}

/// The hidden `KeyHolder` method of a union; empty when not covered.
/// The `KeyHolder` of a union this backend emits a method for: covered by
/// the model, and no case holding a struct whose key reads base members
/// (refused, as in `compute_key_method`).
fn covered_union(u: &Union, idx: &TypeIndex) -> Option<KhUnion> {
    let kh = idx.union_key_holder(u).ok()?;
    let reads_base = kh
        .cases
        .iter()
        .filter_map(|c| c.node.as_ref())
        .any(|n| n.base_member().is_some());
    (!reads_base).then_some(kh)
}

pub(super) fn union_method(u: &Union, idx: &TypeIndex) -> String {
    let Some(kh) = covered_union(u, idx) else {
        return String::new();
    };
    let disc = |i: usize| union_disc_literal(idx, u, i);
    union_key_holder_method(
        &u.name,
        &kh,
        &format!("{MODULE}::KeyHolderWriter"),
        &MicroGenerator::union_variant_name_for_key,
        &disc,
        false,
    )
}
